PREFIX orkgr: <http://orkg.org/orkg/resource/> PREFIX orkgc: <http://orkg.org/orkg/class/> PREFIX orkgp: <http://orkg.org/orkg/predicate/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?paper ?paperLabel ?durationYears ?startTime ?endTime
WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C65000 .
  ?paper rdfs:label ?paperLabel .
  OPTIONAL { ?contribution orkgp:P15594 ?durationYears . }
  OPTIONAL { ?contribution orkgp:wikidata:P580 ?startTime . }
  OPTIONAL { ?contribution orkgp:wikidata:P582 ?endTime . }
}
ORDER BY ?paperLabel

PREFIX orkgr: <http://orkg.org/orkg/resource/> PREFIX orkgc: <http://orkg.org/orkg/class/> PREFIX orkgp: <http://orkg.org/orkg/predicate/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?paper ?paperLabel ?systemLabel ?countryLabel ?locationLabel
WHERE {
  ?paper orkgp:P31 ?paperContribution .
  VALUES ?link1 { orkgp:P115000 orkgp:wikidata:P2974 }
  ?paperContribution ?link1 ?contribution .
  ?contribution a orkgc:C65002 .
  ?paper rdfs:label ?paperLabel .
  OPTIONAL { ?contribution orkgp:wikidata:P1448 ?systemLabel . }
  OPTIONAL { ?contribution orkgp:P37524 ?country . ?country rdfs:label ?countryLabel . }
  OPTIONAL { ?contribution orkgp:wikidata:P276 ?location . ?location rdfs:label ?locationLabel . }
}
ORDER BY ?paperLabel

